package guru.interlis.compiler;

import guru.interlis.compiler.query.*;
import guru.interlis.execution.CancellationToken;
import guru.interlis.model.*;
import guru.interlis.source.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class EditorCompletionTest {
    private static final String PREFIX="INTERLIS 2.4; MODEL M AT \"x\" VERSION \"1\"=DOMAIN Code=TEXT;TOPIC T=STRUCTURE S=note:TEXT;END S;CLASS Base=END Base;";
    static CompletionResult complete(String marked){int pos=marked.indexOf('│');String text=marked.replace("│","");var source=EditorAssistanceTest.source(text);var a=EditorAssistanceTest.analyze(source);int start=pos;while(start>0&&Character.isJavaIdentifierPart(text.charAt(start-1)))start--;return new EditorAssistanceService().complete(a,new CompletionQuery(source.range(pos,pos),new NamePrefix(text.substring(start,pos)),200),CancellationToken.none());}
    static Set<String> labels(CompletionResult r){return new LinkedHashSet<>(r.candidates().stream().map(CompletionCandidate::label).toList());}
    @Test void rootAndContainerTemplatesHaveMirroredNamesAndSeparateBody(){var r=complete("INTERLIS 2.4;\nMO│");assertEquals(Set.of("MODEL","MODEL block"),labels(r));var model=r.candidates().stream().filter(CompletionCandidate::snippet).findFirst().orElseThrow();assertTrue(model.insertText().contains("END $1."));assertTrue(model.insertText().contains("${4:"));r=complete(PREFIX+"CL│\nEND T;END M.");assertEquals(Set.of("CLASS","CLASS block"),labels(r));assertTrue(r.candidates().getLast().insertText().contains("${2}=\n  $0\nEND $1;"));}
    @Test void attributeTargetsAreTypesAndExactQualifiedSegmentIsReplaced(){String text=PREFIX+"CLASS C=attribute: M.Co│de;END C;END T;END M.";var r=complete(text);assertEquals(Set.of("Code"),labels(r));assertEquals("Code".length(),r.replacementRange().length());assertEquals(text.replace("│","").indexOf("Code;END C"),r.replacementRange().startOffset());assertFalse(r.candidates().getFirst().snippet());}
    @Test void extendsAndCollectionSlotsRespectKindAndVersion(){var r=complete(PREFIX+"CLASS C EXTENDS │=END C;END T;END M.");assertTrue(labels(r).contains("Base"),labels(r).toString());assertFalse(labels(r).contains("Code"));r=complete(PREFIX+"CLASS C=items:BAG OF │;END C;END T;END M.");assertTrue(labels(r).contains("S"));assertTrue(labels(r).contains("Code"));r=complete((PREFIX+"CLASS C=items:BAG OF │;END C;END T;END M.").replace("2.4","2.3"));assertTrue(labels(r).contains("S"));assertFalse(labels(r).contains("Code"));r=complete(PREFIX+"CLASS C=when:DA│;END C;END T;END M.");assertTrue(labels(r).contains("DATE"));r=complete((PREFIX+"CLASS C=when:DA│;END C;END T;END M.").replace("2.4","2.3"));assertFalse(labels(r).contains("DATE"));}
    @Test void stringsCommentsAndAssignmentExpressionsDoNotOfferDeclarations(){for(String body:List.of("!! CL│\n","/* CL│ */","CLASS C=label:TEXT:=\"CL│\";END C;","CLASS C=flag:BOOLEAN:=CL│;END C;")){assertTrue(complete(PREFIX+body+"END T;END M.").candidates().stream().noneMatch(c->c.label().equals("CLASS")||c.snippet()),body);}}
    @Test void endSlotUsesOnlyTheContainerIdentifier(){var r=complete(PREFIX+"CLASS C (ABSTRACT)=END │;END T;END M.");assertEquals(Set.of("C"),labels(r));}
    @Test void unusedImportRequiresCompleteBindingAndEditsCommas(){for(String imports:List.of("Unused","Unused, Used","Used, Unused")){var first=EditorAssistanceTest.source("INTERLIS 2.4;MODEL M AT \"x\" VERSION \"1\"=IMPORTS "+imports+";"+(imports.contains("Used")?"DOMAIN D EXTENDS Used.Code=TEXT;":"")+"END M.");var other=new SourceText(new SourceId("memory:/others.ili"),new SourceRevision(1),"INTERLIS 2.4;MODEL Unused AT \"x\" VERSION \"1\"=END Unused.MODEL Used AT \"x\" VERSION \"1\"=DOMAIN Code=TEXT;END Used.");var syntax=CompilerTestSupport.parse(first);var targetSyntax=CompilerTestSupport.parse(other);var bindings=syntax.root().models().getFirst().imports().stream().map(i->CompilerTestSupport.binding(syntax,i.modelName(),other,targetSyntax)).toList();var request=CompilerTestSupport.request(List.of("M"),Map.of(first.id(),first,other.id(),other),bindings,CompilerOptions.defaults());var a=CompilerEngines.create().analyze(request,CancellationToken.none());var plans=new EditorAssistanceService().quickFixes(a,first.range(0,first.length()),CancellationToken.none()).stream().filter(p->p.id().equals("import.unused")).toList();assertEquals(1,plans.size(),()->a.diagnostics()+" "+a.semanticGraph().references());String changed=EditorAssistanceTest.apply(first,plans.getFirst());assertFalse(changed.contains("Unused"));if(imports.contains("Used"))assertTrue(changed.contains("Used;"));var invalid=EditorAssistanceTest.source(first.text().replace("END M.","DOMAIN Broken=Unknown;END M."));var partial=CompilerEngines.create().analyze(new CompilationRequest(request.roots(),SourceSet.of(Map.of(invalid.id(),invalid,other.id(),other),bindings,List.of(),new ResolutionFingerprint("test/v1")),CompilerOptions.defaults()),CancellationToken.none());assertTrue(new EditorAssistanceService().quickFixes(partial,invalid.range(0,invalid.length()),CancellationToken.none()).stream().noneMatch(p->p.id().equals("import.unused")));}}
}
